const WebSocket = require("ws");
const path = require("path");
const fs = require("fs");

const chatbotsPath = path.join(
    __dirname,
    "chatbots.json"
);

const chatbots = JSON.parse(
    fs.readFileSync(chatbotsPath, "utf8")
);



let browser = null;

let browserReadyResolve;

const browserReady = new Promise(resolve => {
    browserReadyResolve = resolve;
});


const wss = new WebSocket.Server({
    host: "127.0.0.1",
    port: 8080
});


console.log("Android AI Bridge");
console.log("ws://127.0.0.1:8080");


wss.on("connection", (ws) => {

    browser = ws;

    console.log("Browser Connected");


    browserReadyResolve();

    setInterval(() => {
        if (browser && browser.readyState === WebSocket.OPEN) {
            browser.send(JSON.stringify({
                type: "ping"
            }));
        }
    }, 5000);


    ws.on("message", (msg) => {

        const data = JSON.parse(msg);

        if (data.id && waiting.has(data.id)) {
            waiting.get(data.id)(data);
            waiting.delete(data.id);
        }

    });

});


const waiting = new Map();
let requestId = 0;




function send(type, data = {}) {

    return new Promise((resolve, reject) => {

        if (!browser) {
            reject(new Error("Browser not connected"));
            return;
        }

        if (browser.readyState !== WebSocket.OPEN) {
            reject(new Error("Socket closed"));
            return;
        }

        const id = ++requestId;

        waiting.set(id, (response) => {

            if (response.ok === false) {
                reject(new Error(response.error));
                return;
            }

            resolve(response);

        });

        browser.send(JSON.stringify({
            id,
            type,
            ...data
        }));

    });

}







process.on("SIGINT", () => {

    console.log("Stopping...");

    if (browser) {
        browser.close();
    }

    wss.close(() => process.exit());

});




module.exports = {
    send,
    browserReady
};